import { PutItemCommand } from 'dynamodb-toolbox/entity/actions/put';
import { ScanCommand } from 'dynamodb-toolbox/table/actions/scan';
import { MODELO_PRODUCTO, MODELO_PANADERIA, TABLA_PRODUCTOS } from '../../models/panaderia-producto.model.mjs';

export async function crearProductoRepository(producto) {
  await MODELO_PRODUCTO.build(PutItemCommand)
    .item(producto)
    .options({ condition: { attr: 'productoId', exists: false } })
    .send();
}

export async function listarProductosRepository() {
  const { Items = [] } = await TABLA_PRODUCTOS.build(ScanCommand)
    .entities(MODELO_PRODUCTO)
    .options({ consistent: true })
    .send();
  return Items;
}

