import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_PRODUCTO, MODELO_PANADERIA, TABLA_PRODUCTOS } from '../../models/panaderia-producto.model.mjs';

export async function buscarPanaderiaRepository(panaderiaId) {
  const { Item } = await MODELO_PANADERIA.build(GetItemCommand)
    .key({ panaderiaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarPanaderiaRepository(panaderiaId, minimo) {
  const { Items = [] } = await TABLA_PRODUCTOS.build(QueryCommand)
    .entities(MODELO_PRODUCTO)
    .query({ index: 'PorPanaderia', partition: panaderiaId })
    .options({ filters: { Producto: { attr: 'precioCentimos', gte: minimo } } })
    .send();
  return Items;
}
